	const PmSkillInfo* PmSkillInfoFor(int idx) {
		for (const PmSkillInfo& i : SKILL_INFO)
			if (i.idx == idx)
				return &i;
		return nullptr;
	}

	int PmSkillInfoCount() {
		return (int)(sizeof(SKILL_INFO) / sizeof(SKILL_INFO[0]));
	}
